    [Theory]
    [MemberData(nameof(Programs))]
    public async Task SplitDirectionsUnicodeAndRetainedWordsFollowPython(string source, string expected)
    {
        var budget = new LythonMemoryBudget(8 * 1024 * 1024);
        using (var script = new LythonEngine().Compile(source, budget))
        {
            Assert.True(script.IsValid, string.Join("; ", script.Diagnostics.Select(d => d.Message)));
            var baseline = budget.ReservedBytes;
            foreach (var asynchronous in new[] { false, true })
            {
                using (var result = asynchronous ? await script.RunAsync(new MockLythonHost()) : script.Run(new MockLythonHost()))
                {
                    Assert.True(result.Success, result.Failure?.Message);
                    Assert.Equal(expected, result.StandardOutput);
                }
                Assert.Equal(baseline, budget.ReservedBytes);
            }
        }
        Assert.Equal(0, budget.ReservedBytes);
    }

    [Fact]
    public async Task EscapingWordsKeepIndependentStorageAcrossSharedBudgetExecutions()
    {
        const string source = """
            def words(value): return value.upper().split()
            result=[word for word in words(('ßé'*256)+' saved')]
            return result,result[0]
            """;
        var budget = new LythonMemoryBudget(4 * 1024 * 1024);
        using (var script = new LythonEngine().Compile(source, budget))
        {
            Assert.True(script.IsValid);
            var baseline = budget.ReservedBytes;
            var expected = string.Concat(Enumerable.Repeat("SSÉ", 256));
            using (var first = script.Run(new MockLythonHost()))
            {
                Assert.True(first.Success, first.Failure?.Message);
                var firstParts = Assert.IsAssignableFrom<IReadOnlyList<object>>(first.ReturnValue);
                Assert.Equal(expected, firstParts[1]);
                var retained = budget.ReservedBytes;
                Assert.True(retained > baseline);
                using (var second = await script.RunAsync(new MockLythonHost()))
                {
                    Assert.True(second.Success, second.Failure?.Message);
                    Assert.Equal(expected, firstParts[1]);
                    Assert.Equal(expected, Assert.IsAssignableFrom<IReadOnlyList<object>>(second.ReturnValue)[1]);
                    Assert.True(budget.ReservedBytes > retained);
                }
                Assert.Equal(retained, budget.ReservedBytes);
                Assert.Equal(expected, firstParts[1]);
            }
            Assert.Equal(baseline, budget.ReservedBytes);
        }
        Assert.Equal(0, budget.ReservedBytes);
    }
}
